<template><aside class="quick-access" :class="{'is-open':opened}"><div class="quick-access__items"><template v-for="item in quickItems" :key="item.id"><router-link v-if="item.to" class="quick-access__item" :to="item.to" :aria-label="item.label"><component :is="item.icon" :size="20"/><span>{{ item.label }}</span></router-link><button v-else class="quick-access__item" type="button" @click="emit('line')"><component :is="item.icon" :size="20"/><span>{{ item.label }}</span></button></template></div><button class="quick-access__trigger" type="button" :aria-expanded="opened" :aria-label="opened?'關閉快速功能':'開啟快速功能'" @click="opened=!opened"><Heart :size="24"/></button></aside></template>
<script setup lang="ts">import{markRaw,ref}from'vue';import type{RouteLocationRaw}from'vue-router';import{Heart,MessageCircleHeart,UserRound,UserRoundCheck}from'@lucide/vue';interface MenuItem{id:string;label:string;icon:any;to?:RouteLocationRaw;action?:'line'}const opened=ref(false);const emit=defineEmits<{line:[]}>();const quickItems:MenuItem[]=[{id:'nurse-login',label:'居服員登入',icon:markRaw(UserRoundCheck),to:{name:'login'}},{id:'user-login',label:'使用者登入',icon:markRaw(UserRound),to:{name:'login'}},{id:'line',label:'LINE 客服',icon:markRaw(MessageCircleHeart),action:'line'}];</script>
<style scoped>.quick-access{position:fixed;z-index:40;right:24px;top:50%;display:flex;flex-direction:column;align-items:flex-end;gap:12px;transform:translateY(-50%)}.quick-access__items{display:flex;flex-direction:column;align-items:flex-end;gap:10px}.quick-access__item{min-height:46px;display:flex;align-items:center;gap:8px;padding:0 15px;color:#493833;background:#fffdfb;border:1px solid #c8561830;border-radius:999px;box-shadow:0 8px 24px #2d201926;text-decoration:none;font:inherit;font-weight:700;cursor:pointer;opacity:0;transform:translateY(10px) scale(.96);pointer-events:none;transition:opacity .2s ease,transform .2s ease}.is-open .quick-access__item{opacity:1;transform:none;pointer-events:auto}.is-open .quick-access__item:nth-child(2){transition-delay:.04s}.is-open .quick-access__item:nth-child(3){transition-delay:.08s}.quick-access__trigger{width:56px;height:56px;display:grid;place-items:center;padding:0;color:#fff;background:#c85618;border:0;border-radius:50%;box-shadow:0 10px 26px #5c240f4d;cursor:pointer}.quick-access__trigger:focus-visible,.quick-access__item:focus-visible{outline:3px solid #fff;outline-offset:3px}@media(max-width:900px){.quick-access{right:12px;top:86px;transform:none}.quick-access__trigger{width:52px;height:52px}.quick-access__items{order:2}.quick-access__trigger{order:1}.quick-access__item{min-height:44px;padding-inline:12px;font-size:.82rem}}@media(prefers-reduced-motion:reduce){.quick-access__item{transition:none}}</style>
